ce":51000,"note":"Mèo, po, cf","createdAt":"2026-08-04T05:00:00.000Z","payments":[],"source":"excel-so-no-thang-8-2026","kind":"manual"},{"id":"excel-2026-08-05-kh-linh-tdt-57000","customerId":"kh-linh-tdt","customer":"Linh TĐT","amount":57000,"paid":0,"balance":57000,"note":"Sg bạc, 3c","createdAt":"2026-08-05T05:00:00.000Z","payments":[],"source":"excel-so-no-thang-8-2026","kind":"manual"},{"id":"excel-2026-08-05-kh-son-dt-90000","customerId":"kh-son-dt","customer":"Sơn DT","amount":90000,"paid":0,"balance":90000,"note":"2 omo, 1kem đánh răng","createdAt":"2026-08-05T05:00:00.000Z","payments":[],"source":"excel-so-no-thang-8-2026","kind":"manual"}]'::jsonb;
  v_active_id text;
  v_store_index integer := 0;
  v_i integer;
  v_found boolean := false;
  v_store_data jsonb;
begin
  select data into v_data
  from public.cantin_app_store
  where id = 'main'
  for update;

  if v_data is null then
    raise exception 'Không tìm thấy dữ liệu cửa hàng id=main.';
  end if;

  -- Cấu trúc nhiều cửa hàng v2.5
  if coalesce((v_data->>'__multiStore')::boolean, false)
     and jsonb_typeof(v_data->'stores') = 'array'
     and jsonb_array_length(v_data->'stores') > 0 then

    v_active_id := v_data->>'activeStoreId';

    for v_i in 0..jsonb_array_length(v_data->'stores') - 1 loop
      if (v_data->'stores'->v_i->>'id') = v_active_id then
        v_store_index := v_i;
        v_found := true;
        exit;
      end if;
    end loop;

    if not v_found then
      v_store_index := 0;
    end if;

    v_store_data := coalesce(v_data->'stores'->v_store_index->'data', '{}'::jsonb);
    v_store_data := jsonb_set(v_store_data, '{customers}', v_customers, true);
    v_store_data := jsonb_set(v_store_data, '{debts}', v_debts, true);

    -- Đảm bảo các mảng quan trọng không bị undefined
    if not (v_store_data ? 'products') then
      v_store_data := jsonb_set(v_store_data, '{products}', '[]'::jsonb, true);
    end if;
    if not (v_store_data ? 'sales') then
      v_store_data := jsonb_set(v_store_data, '{sales}', '[]'::jsonb, true);
    end if;
    if not (v_store_data ? 'weeklyAudits') then
      v_store_data := jsonb_set(v_store_data, '{weeklyAudits}', '[]'::jsonb, true);
    end if;
    if not (v_store_data ? 'weeklyTemplate') then
      v_store_data := jsonb_set(v_store_data, '{weeklyTemplate}', '[]'::jsonb, true);
    end if;
    if not (v_store_data ? 'stockAdjustments') then
      v_store_data := jsonb_set(v_store_data, '{stockAdjustments}', '[]'::jsonb, true);
    end if;

    v_data := jsonb_set(
      v_data,
      array['stores', v_store_index::text, 'data'],
      v_store_data,
      true
    );

  -- Cấu trúc cũ v2.3/v2.4
  else
    v_data := jsonb_set(v_data, '{customers}', v_customers, true);
    v_data := jsonb_set(v_data, '{debts}', v_debts, true);

    if not (v_data ? 'products') then
      v_data := jsonb_set(v_data, '{products}', '[]'::jsonb, true);
    end if;
    if not (v_data ? 'sales') then
      v_data := jsonb_set(v_data, '{sales}', '[]'::jsonb, true);
    end if;
    if not (v_data ? 'weeklyAudits') then
      v_data := jsonb_set(v_data, '{weeklyAudits}', '[]'::jsonb, true);
    end if;
    if not (v_data ? 'weeklyTemplate') then
      v_data := jsonb_set(v_data, '{weeklyTemplate}', '[]'::jsonb, true);
    end if;
    if not (v_data ? 'stockAdjustments') then
      v_data := jsonb_set(v_data, '{stockAdjustments}', '[]'::jsonb, true);
    end if;
  end if;

  update public.cantin_app_store
  set data = v_data,
      updated_at = now()
  where id = 'main';
end $$;

-- Kiểm tra kết quả:
select
  case
    when coalesce((data->>'__multiStore')::boolean, false)
      then jsonb_array_length(
        (select s->'data'->'customers'
         from jsonb_array_elements(data->'stores') s
         where s->>'id' = data->>'activeStoreId'
         limit 1)
      )
    else jsonb_array_length(data->'customers')
  end as so_khach,
  case
    when coalesce((data->>'__multiStore')::boolean, false)
      then jsonb_array_length(
        (select s->'data'->'debts'
         from jsonb_array_elements(data->'stores') s
         where s->>'id' = data->>'activeStoreId'
         limit 1)
      )
    else jsonb_array_length(data->'debts')
  end as so_khoan_no
from public.cantin_app_store
where id = 'main';
